@namespace sv_9876aa43dff047af874120472ae1beea.Components.Pages.Settings
@using sv_9876aa43dff047af874120472ae1beea.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (isLoading)
    {
        <p class="loading">Loading preferences...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="emailNotifications" />
                <span class="toggle-label">Email Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="pushNotifications" />
                <span class="toggle-label">Push Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="weeklyDigest" />
                <span class="toggle-label">Weekly Digest</span>
            </label>
        </div>

        <div class="channels-section">
            <h3>Muted Channels</h3>
            @foreach (var channel in allChannels)
            {
                <label class="toggle-item">
                    <input type="checkbox"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <span class="toggle-label">@channel</span>
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SavePreferences" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="toast success">Preferences saved successfully!</div>
        }
    }
</div>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    // Example channels — in a real app these would come from a service
    private static readonly string[] allChannels = ["general", "announcements", "random", "engineering", "design", "marketing"];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        isSaving = true;
        showSuccess = false;

        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);

        isSaving = false;
        showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

